def combine_alphas(alpha_matrix, ic_weights):
    cov = alpha_matrix.cov().values + 1e-4 * np.eye(alpha_matrix.shape[1])
    weights = np.linalg.solve(cov, ic_weights)
    weights /= np.sum(np.abs(weights))
    return alpha_matrix.dot(weights)

def orthogonalize_signal(candidate, existing_basis):
    residual = candidate.copy()
    for base in existing_basis:
        proj = np.dot(residual, base) / np.dot(base, base)
        residual -= proj * base
    return residual / np.linalg.norm(residual)

