def calculate_alpha_beta(asset_returns, market_returns):
    cov = np.cov(asset_returns, market_returns)[0, 1]
    beta = cov / np.var(market_returns)
    alpha = np.mean(asset_returns) - beta * np.mean(market_returns)
    return float(alpha), float(beta)

