def estimate_ate(treatment, outcome, confounders):
    ps = LogisticRegression().fit(confounders, treatment).predict_proba(confounders)[:, 1]
    weights = treatment/ps + (1-treatment)/(1-ps)
    return float(np.average(outcome * (treatment - (1-treatment)), weights=weights))

