def compute_deflated_sharpe(returns, num_trials=100):
    sr = np.mean(returns) / np.std(returns) * np.sqrt(252)
    e_max = (1 - 0.5772) * norm.ppf(1 - 1.0/num_trials) + 0.5772 * norm.ppf(1 - 1.0/(num_trials * np.e))
    dsr = norm.cdf((sr - e_max) / np.sqrt(1 + 0.5 * sr**2))
    return float(dsr)

