def deflated_sharpe_proof(sr, n, skew, kurt):
    var_sr = (1 - skew*sr + (kurt - 1)/4.0 * sr**2) / 252.0
    emax = np.sqrt(2 * np.log(n))
    return float(norm.cdf((sr - emax) / np.sqrt(var_sr)))

